using UnityEngine;

// Author : Baptiste Vu Liem
namespace Com.IsartDigital.GoobyrFPS.FX
{
    /// <summary>
    /// Shared materials (generated by the art builder into <c>Resources/Art</c>) and the colour
    /// helpers every procedural visual uses. Colours go through vertex colours or a property block
    /// so the whole game runs on a handful of materials.
    /// </summary>
    public static class GameArt
    {
        private static Material _toon, _transparent, _glow, _particle, _particleAlpha;
        private static MaterialPropertyBlock _block;

        public static readonly int BaseColor = Shader.PropertyToID("_BaseColor");
        public static readonly int HitFlash = Shader.PropertyToID("_HitFlash");
        public static readonly int Emission = Shader.PropertyToID("_EmissionColor");

        public static Material Toon => _toon != null ? _toon : _toon = Load("Art/M_Toon", "Goobyr/Toon");
        public static Material Transparent => _transparent != null ? _transparent : _transparent = Load("Art/M_ToonTransparent", "Goobyr/ToonTransparent");
        /// <summary>Unlit, emissive: muzzle flashes, tracers, fire, lights' bulbs.</summary>
        public static Material Glow => _glow != null ? _glow : _glow = Load("Art/M_Glow", "Goobyr/Glow");
        /// <summary>Additive particles (fire, sparks, flashes).</summary>
        public static Material ParticleAdd => _particle != null ? _particle : _particle = Load("Art/M_ParticleAdd", "Goobyr/Glow");
        /// <summary>Alpha-blended particles (smoke, dust, gas).</summary>
        public static Material ParticleAlpha => _particleAlpha != null ? _particleAlpha : _particleAlpha = Load("Art/M_ParticleAlpha", "Goobyr/Glow");

        private static Material Load(string pPath, string pFallbackShader)
        {
            Material lMaterial = Resources.Load<Material>(pPath);
            if (lMaterial == null)
            {
                Shader lShader = Shader.Find(pFallbackShader);
                lMaterial = new Material(lShader != null ? lShader : Shader.Find("Universal Render Pipeline/Unlit"));
            }
            return lMaterial;
        }

        /// <summary>Tints one renderer without a new material.</summary>
        public static void Paint(Renderer pRenderer, Color pColor)
        {
            _block ??= new MaterialPropertyBlock();
            pRenderer.GetPropertyBlock(_block);
            _block.SetColor(BaseColor, pColor);
            pRenderer.SetPropertyBlock(_block);
        }

        public static void SetFlash(Renderer pRenderer, float pFlash)
        {
            _block ??= new MaterialPropertyBlock();
            pRenderer.GetPropertyBlock(_block);
            _block.SetFloat(HitFlash, pFlash);
            pRenderer.SetPropertyBlock(_block);
        }

        public static void SetEmission(Renderer pRenderer, Color pColor)
        {
            _block ??= new MaterialPropertyBlock();
            pRenderer.GetPropertyBlock(_block);
            _block.SetColor(Emission, pColor);
            pRenderer.SetPropertyBlock(_block);
        }

        /// <summary>A child with a mesh and the toon material, tinted.</summary>
        public static GameObject Part(Transform pParent, string pName, Mesh pMesh, Vector3 pLocalPos, Vector3 pScale, Color pColor, Material pMaterial = null)
        {
            GameObject lPart = new GameObject(pName);
            lPart.transform.SetParent(pParent, false);
            lPart.transform.localPosition = pLocalPos;
            lPart.transform.localScale = pScale;
            lPart.AddComponent<MeshFilter>().sharedMesh = pMesh;
            MeshRenderer lRenderer = lPart.AddComponent<MeshRenderer>();
            lRenderer.sharedMaterial = pMaterial != null ? pMaterial : Toon;
            Paint(lRenderer, pColor);
            return lPart;
        }

        public static Color Hex(string pHex) => ColorUtility.TryParseHtmlString(pHex, out Color lColor) ? lColor : Color.magenta;

        public static Color Vary(Color pColor, float pAmount, System.Random pRandom)
        {
            Color.RGBToHSV(pColor, out float h, out float s, out float v);
            h = Mathf.Repeat(h + ((float)pRandom.NextDouble() - 0.5f) * pAmount * 0.15f, 1f);
            v = Mathf.Clamp01(v + ((float)pRandom.NextDouble() - 0.5f) * pAmount);
            return Color.HSVToRGB(h, s, v);
        }
    }
}
